CREATE TABLE IF NOT EXISTS ai.company_contexts (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, version integer NOT NULL, content_jsonb jsonb NOT NULL, source text, status text NOT NULL, updated_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (company_id, version));
CREATE UNIQUE INDEX IF NOT EXISTS company_contexts_one_effective ON ai.company_contexts (company_id) WHERE status = 'effective';
CREATE TABLE IF NOT EXISTS ai.article_relevance (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, article_snapshot_id text NOT NULL, context_id text NOT NULL, relevance text NOT NULL CHECK (relevance IN ('high','medium','low','none')), confidence numeric, rationale text, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (company_id, article_snapshot_id, context_id));
CREATE INDEX IF NOT EXISTS article_relevance_company_idx ON ai.article_relevance (company_id, relevance);
CREATE TABLE IF NOT EXISTS ai.issues (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, title text, one_liner text, status text NOT NULL CHECK (status IN ('baru','berkembang','dipantau','selesai')), current_priority text CHECK (current_priority IS NULL OR current_priority IN ('tinggi','sedang','rendah')), first_seen_at timestamptz NOT NULL, last_developed_at timestamptz NOT NULL, version integer NOT NULL, closed_at timestamptz, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS issues_dashboard_idx ON ai.issues (company_id, status, current_priority, last_developed_at DESC, id);
CREATE TABLE IF NOT EXISTS ai.issue_articles (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, issue_id text NOT NULL REFERENCES ai.issues(id), article_snapshot_id text NOT NULL, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, attached_at timestamptz NOT NULL, relation_status text NOT NULL DEFAULT 'active', UNIQUE (issue_id, article_snapshot_id));
CREATE TABLE IF NOT EXISTS ai.issue_developments (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, issue_id text NOT NULL REFERENCES ai.issues(id), article_snapshot_id text, development_type text NOT NULL, observed_at timestamptz NOT NULL, is_material boolean, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS issue_developments_issue_idx ON ai.issue_developments (issue_id, observed_at DESC);
CREATE TABLE IF NOT EXISTS ai.issue_analyses (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, issue_id text NOT NULL REFERENCES ai.issues(id), input_fingerprint text NOT NULL, prompt_version text NOT NULL, status text NOT NULL, analysis_jsonb jsonb NOT NULL, evidence_jsonb jsonb NOT NULL DEFAULT '[]'::jsonb, provenance_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, valid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (issue_id, input_fingerprint, prompt_version));
CREATE TABLE IF NOT EXISTS ai.issue_priorities (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, issue_id text NOT NULL REFERENCES ai.issues(id), analysis_id text NOT NULL REFERENCES ai.issue_analyses(id), priority text NOT NULL CHECK (priority IN ('tinggi','sedang','rendah')), reason text, rule_version text, provenance_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, effective_at timestamptz NOT NULL, superseded_at timestamptz);
CREATE TABLE IF NOT EXISTS ai.stage_runs (id text PRIMARY KEY, pipeline_run_id text, tenant_id text, company_id text, task text NOT NULL, input_fingerprint text, output_jsonb jsonb, validation_status text, model text, prompt_id text, prompt_version text, provider_request_id text, attempts integer NOT NULL DEFAULT 1, started_at timestamptz, completed_at timestamptz, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai.alert_preferences (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, user_ref text NOT NULL, direct_high_enabled boolean NOT NULL, daily_digest_enabled boolean NOT NULL, timezone text NOT NULL, quiet_hours_jsonb jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (company_id, user_ref));
CREATE TABLE IF NOT EXISTS ai.alert_events (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, issue_id text, development_id text, recipient_ref text, channel text NOT NULL, reason_code text, dedupe_key text NOT NULL UNIQUE, status text NOT NULL, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), content_blocked_at timestamptz, delivery_blocked_at timestamptz);
CREATE TABLE IF NOT EXISTS ai.email_deliveries (id text PRIMARY KEY, alert_event_id text REFERENCES ai.alert_events(id), report_id text, tenant_id text NOT NULL, company_id text NOT NULL, recipient_ref text, recipient_hash text, template_version text NOT NULL, subject text NOT NULL, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL, provider_message_ref text, attempts_jsonb jsonb NOT NULL DEFAULT '[]'::jsonb, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE IF NOT EXISTS ai.reports (id text PRIMARY KEY, tenant_id text NOT NULL, company_id text NOT NULL, report_type text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, timezone text NOT NULL, review_status text NOT NULL, current_version_id text, payload_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (company_id, report_type, period_start, period_end));
CREATE TABLE IF NOT EXISTS ai.report_versions (id text PRIMARY KEY, report_id text NOT NULL REFERENCES ai.reports(id), version integer NOT NULL, content_jsonb jsonb NOT NULL, metrics_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, provenance_jsonb jsonb NOT NULL DEFAULT '{}'::jsonb, review_status text NOT NULL, author_ref text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (report_id, version));
CREATE TABLE IF NOT EXISTS ai.report_items (id text PRIMARY KEY, report_version_id text NOT NULL REFERENCES ai.report_versions(id), issue_id text NOT NULL REFERENCES ai.issues(id), section text, rank integer, inclusion_reason text);
